"""Order total calculation: line amounts, tax and shipping.

Rules (see README):

* line amount = unit price x quantity;
* tax is charged on top of the price, per line, at the rate of the line's category,
  and rounded per line (ROUND_HALF_UP); the order tax is the sum of line taxes;
* shipping is a flat fee, free when the goods subtotal reaches the threshold;
  carts with gift cards only are not shipped at all;
* shipping is not taxed;
* a promo discount is allocated over eligible lines (never gift cards), tax is charged
  on the line amount after discount, shipping uses the pre-discount subtotal.
"""

from __future__ import annotations

import logging
from collections.abc import Mapping
from dataclasses import dataclass, field
from decimal import Decimal
from types import MappingProxyType

from .catalog import Cart, Category
from .errors import EmptyCartError, PromoConditionsError, ValidationError
from .money import CENT, ZERO, quantize_money, sum_money
from .promo import DiscountKind, PromoCode

logger = logging.getLogger(__name__)

DEFAULT_TAX_RATE = Decimal("0.20")
DEFAULT_TAX_RATES: Mapping[Category, Decimal] = MappingProxyType(
    {
        Category.BOOKS: Decimal("0.10"),
        Category.FOOD: Decimal("0.10"),
        Category.GIFT_CARD: Decimal("0"),
    }
)


@dataclass(frozen=True)
class TaxPolicy:
    rates: Mapping[Category, Decimal] = field(default_factory=lambda: DEFAULT_TAX_RATES)
    default_rate: Decimal = DEFAULT_TAX_RATE

    def __post_init__(self) -> None:
        for rate in (*self.rates.values(), self.default_rate):
            if not Decimal("0") <= rate < Decimal("1"):
                raise ValidationError(f"tax rate out of range: {rate}")

    def rate_for(self, category: Category) -> Decimal:
        return self.rates.get(category, self.default_rate)

    def tax_for(self, category: Category, taxable_amount: Decimal) -> Decimal:
        return quantize_money(taxable_amount * self.rate_for(category))


@dataclass(frozen=True)
class ShippingPolicy:
    fee: Decimal = Decimal("299.00")
    free_threshold: Decimal | None = Decimal("3000.00")

    def __post_init__(self) -> None:
        if self.fee < 0:
            raise ValidationError("shipping fee must not be negative")
        if self.free_threshold is not None and self.free_threshold < 0:
            raise ValidationError("free shipping threshold must not be negative")

    def cost_for(self, goods_amount: Decimal, *, needs_delivery: bool) -> Decimal:
        if not needs_delivery:
            return ZERO
        if self.free_threshold is not None and goods_amount >= self.free_threshold:
            return ZERO
        return quantize_money(self.fee)


@dataclass(frozen=True)
class LineTotal:
    sku: str
    category: Category
    quantity: int
    unit_price: Decimal
    amount: Decimal
    tax: Decimal
    discount: Decimal = ZERO


@dataclass(frozen=True)
class OrderTotal:
    lines: tuple[LineTotal, ...]
    subtotal: Decimal
    shipping: Decimal
    tax: Decimal
    total: Decimal
    discount: Decimal = ZERO

    @property
    def items_count(self) -> int:
        return sum(line.quantity for line in self.lines)


DEFAULT_SHIPPING = ShippingPolicy()
DEFAULT_TAX = TaxPolicy()


def _allocate_discount(amounts: list[Decimal], discount: Decimal) -> list[Decimal]:
    """Split ``discount`` over ``amounts`` proportionally, to the kopeck.

    Largest remainder method; ties go to the earlier line. The parts sum exactly to
    ``discount`` and no part exceeds its amount (discount <= sum of amounts).
    """
    cents = [int(a / CENT) for a in amounts]
    total_cents = sum(cents)
    to_split = int(discount / CENT)
    shares = [to_split * c // total_cents for c in cents]
    remainders = [to_split * c % total_cents for c in cents]
    left = to_split - sum(shares)
    order = sorted(range(len(cents)), key=lambda i: (-remainders[i], i))
    for i in order[:left]:
        shares[i] += 1
    return [Decimal(share) * CENT for share in shares]


def _promo_discount(promo: PromoCode, eligible: Decimal, subtotal: Decimal) -> Decimal:
    if subtotal < promo.min_order_amount:
        raise PromoConditionsError(
            f"order amount {subtotal} is below the minimum {promo.min_order_amount}"
        )
    if eligible <= 0:
        raise PromoConditionsError(f"promo {promo.code} does not apply to any item in the order")
    if promo.kind is DiscountKind.PERCENT:
        return min(quantize_money(eligible * promo.value / 100), eligible)
    return min(quantize_money(promo.value), eligible)


def calculate_total(
    cart: Cart,
    shipping: ShippingPolicy | None = None,
    tax: TaxPolicy | None = None,
    *,
    promo: PromoCode | None = None,
) -> OrderTotal:
    """Calculate the totals of ``cart``. Pure function: does not modify the cart.

    With ``promo`` only the order conditions (minimum amount, applicable items) are
    checked here; validity period and usage limit are checked by the registry.
    """
    if cart.is_empty:
        raise EmptyCartError("cannot calculate total of an empty cart")
    shipping = shipping or DEFAULT_SHIPPING
    tax = tax or DEFAULT_TAX

    cart_lines = list(cart.lines)
    subtotal = sum_money(cl.amount for cl in cart_lines)
    discounts = [ZERO] * len(cart_lines)
    if promo is not None:
        eligible_idx = [
            i
            for i, cl in enumerate(cart_lines)
            if cl.product.category is not Category.GIFT_CARD
            and cl.product.category not in promo.excluded_categories
        ]
        eligible = sum_money(cart_lines[i].amount for i in eligible_idx)
        total_discount = _promo_discount(promo, eligible, subtotal)
        parts = _allocate_discount([cart_lines[i].amount for i in eligible_idx], total_discount)
        for i, part in zip(eligible_idx, parts):
            discounts[i] = part

    lines: list[LineTotal] = []
    for cart_line, line_discount in zip(cart_lines, discounts):
        product = cart_line.product
        amount = cart_line.amount
        lines.append(
            LineTotal(
                sku=product.sku,
                category=product.category,
                quantity=cart_line.quantity,
                unit_price=product.price,
                amount=amount,
                tax=tax.tax_for(product.category, amount - line_discount),
                discount=line_discount,
            )
        )

    discount_total = sum_money(line.discount for line in lines)
    needs_delivery = any(cl.product.is_physical for cl in cart_lines)
    shipping_cost = shipping.cost_for(subtotal, needs_delivery=needs_delivery)
    tax_total = sum_money(line.tax for line in lines)
    total = subtotal - discount_total + shipping_cost + tax_total

    logger.debug(
        "total: subtotal=%s discount=%s shipping=%s tax=%s total=%s",
        subtotal,
        discount_total,
        shipping_cost,
        tax_total,
        total,
    )
    return OrderTotal(
        lines=tuple(lines),
        subtotal=subtotal,
        shipping=shipping_cost,
        tax=tax_total,
        total=total,
        discount=discount_total,
    )
